var n=`0448-hangikjot`;var t=`world-0448`;var a=`IS`;var s=`northern-europe`;var o=4;var r=111;var l={en:`Hangikjöt`,ua:`Копчена баранина`};var d={en:`A traditional dish from Iceland, centered on lamb, smoked salt, potato, frozen green peas. A measured home-kitchen version organized by cooking step. Fresh lamb seasoned with smoked salt replaces traditional Icelandic cold-smoked hangikjöt, which is unavailable in the catalog.`,ua:`Традиційна страва кухні країни Ісландія. Основні складники: ягнятина, копчена сіль, картопля, заморожений зелений горошок. Домашній варіант із кількостями продуктів за етапами приготування. Свіжа баранина з копченою сіллю замінює традиційну ісландську копчену баранину, якої немає в каталозі.`};var g=[{en:`Poach the listed ingredients in barely simmering liquid for about 55 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 55 хвилин до готовності й м’якості.`,t:[`poaching`],m:55,i:[[`lamb`,800,`g`],[`smoked-salt`,6,`g`],[`water`,1300,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 24 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 24 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:24,i:[[`potato`,700,`g`]]},{en:`Cook the listed ingredients in simmering water for about 30 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 30 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:30,i:[[`frozen-green-peas`,280,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`unsalted-butter`,40,`g`]]}];var m={slug:n,id:t,country:`IS`,region:s,servings:4,minutes:111,title:l,text:d,steps:g};export{a as country,m as default,t as id,r as minutes,s as region,o as servings,n as slug,g as steps,d as text,l as title};